#include "installer.h"
#include "libc.h"
#include "config.h"
#include "console.h"
#include "keyboard.h"
#include "ahci.h"
#include "shell.h"

#include "boot_bin.h"      /* generated by tools/pack_fs.py */
#include "fs_bin.h"

/* Changes vs. the original run_installer():
 *  - it picked "the second SATA port" (or the first if there was one) and WIPED it without asking.
 *    The user now chooses the disk when several exist and must type YES.
 *  - the wipe wrote 321 sectors with 321 separate DMA commands; it now uses 32-sector chunks.
 *  - the kernel is written with a single call; every step reports which sector failed. */

#define CHUNK_SECTORS 32u
static uint8_t zeros[CHUNK_SECTORS * SECTOR_SIZE];       /* .bss: already zero */

static bool step(const char* what, bool ok) {
    printf("%s... %s\n", what, ok ? "done" : "FAILED");
    return ok;
}

static bool wipe(const BlockDev* d) {
    for (uint32_t s = 0; s < WIPE_SECTORS; s += CHUNK_SECTORS) {
        uint32_t n = WIPE_SECTORS - s < CHUNK_SECTORS ? WIPE_SECTORS - s : CHUNK_SECTORS;
        if (!bd_write(d, s, n, zeros)) { printf("(write failed at sector %u) ", s); return false; }
    }
    return true;
}

static void install_to(const BlockDev* d) {
    static uint8_t boot_sector[SECTOR_SIZE];
    memset(boot_sector, 0, sizeof boot_sector);
    memcpy(boot_sector, boot_bin, boot_bin_len > SECTOR_SIZE ? SECTOR_SIZE : boot_bin_len);

    uint32_t fs_sectors = (fs_bin_len + SECTOR_SIZE - 1) / SECTOR_SIZE;

    if (!step("Erasing target sectors", wipe(d))) return;
    if (!step("Writing boot sector", bd_write(d, 0, 1, boot_sector))) return;
    /* The running kernel image is still in RAM exactly where the bootloader put it. */
    if (!step("Writing kernel image", bd_write(d, 1, KERNEL_SECTORS, (const void*)KERNEL_LOAD_ADDR))) return;
    if (!step("Writing program filesystem", bd_write(d, FS_DIR_SECTOR, fs_sectors, fs_bin))) return;
    step("Flushing drive cache", bd_flush(d));
    console_puts("\ninpsos has been installed. Remove the installation media and restart (type 'reboot').\n");
}

static void do_install(void) {
    int n = ahci_disk_count();
    if (n < 1) { console_puts("No SATA disk detected. Make sure the controller is in AHCI mode.\n"); return; }

    int pick = 0;
    if (n > 1) {
        printf("%d disks found (0..%d). Install to which one? ", n, n - 1);
        char line[16];
        shell_read_command("", line, sizeof line);
        if (line[0] < '0' || line[0] >= '0' + n || line[1]) { console_puts("Cancelled.\n"); return; }
        pick = line[0] - '0';
    }
    printf("This will ERASE the first %u sectors of disk %d.\n", WIPE_SECTORS, pick);
    char answer[8];
    shell_read_command("Type YES to continue: ", answer, sizeof answer);
    if (strcmp(answer, "YES") != 0) { console_puts("Cancelled.\n"); return; }
    install_to(ahci_disk(pick));
}

void installer_shell(void) {
    console_puts("Installer started.\nCommands: install, reboot\n\n");
    char line[64];
    for (;;) {
        if (shell_read_command("installer> ", line, sizeof line) == 0) continue;
        if (strcmp(line, "install") == 0) do_install();
        else if (strcmp(line, "reboot") == 0) kbd_reboot();
        else console_puts("Unsupported command. The installer only supports 'install' and 'reboot'.\n");
    }
}
